INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Arbeitsraumgestaltung nur für Büros relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Werkstätten oder Homeoffice"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer guten Arbeitsraumgestaltung?', 3, '[{"text": "Produktivität steigern", "correct": true, "because": "Fördert Effizienz"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Technologie verbessern", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Arbeitsraumgestaltung?', 5, '[{"text": "Ergonomische Möbel", "correct": true, "because": "Unterstützt Gesundheit"}, {"text": "Beleuchtung", "correct": true, "because": "Beeinflusst Arbeitsklima"}, {"text": "Software", "correct": false, "because": "Kein Gestaltungselement"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitsraumgestaltung fördert Wohlbefinden. b) Sie ist immer teuer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeitsraumgestaltung?', 4, '[{"text": "Ergonomie", "correct": false, "because": "Schlüsselaspekt"}, {"text": "Raumnutzung", "correct": false, "because": "Effizienz wichtig"}, {"text": "Mitarbeiternamen", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Beleuchtung zur Arbeitsraumgestaltung gehört?', 2, '[{"text": "Ja", "correct": true, "because": "Beeinflusst Arbeitsklima"}, {"text": "Nein", "correct": false, "because": "Teil der Gestaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für die Gesundheit bei der Arbeitsraumgestaltung entscheidend?', 3, '[{"text": "Ergonomische Stühle", "correct": true, "because": "Schont Rücken"}, {"text": "Dekoration", "correct": false, "because": "Ästhetisch, nicht gesundheitlich"}, {"text": "Lautsprecher", "correct": false, "because": "Kein Gesundheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu einer modernen Arbeitsraumgestaltung?', 5, '[{"text": "Flexible Arbeitsplätze", "correct": true, "because": "Fördert Anpassung"}, {"text": "Akustikoptimierung", "correct": true, "because": "Reduziert Lärm"}, {"text": "Softwarelizenzen", "correct": false, "because": "Kein Raumfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Arbeitsraumgestaltung beeinflusst die Produktivität. b) Sie ist nur für große Firmen wichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Firmen profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Arbeitsraumgestaltung unwichtig?', 4, '[{"text": "Belüftung", "correct": false, "because": "Beeinflusst Wohlbefinden"}, {"text": "Raumaufteilung", "correct": false, "because": "Effizienz entscheidend"}, {"text": "Firmenlogo", "correct": true, "because": "Kein funktionaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Arbeitsraumgestaltung statisch?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibel anpassbar"}, {"text": "Ja", "correct": false, "because": "Veränderbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine gute Arbeitsraumgestaltung?', 4, '[{"text": "Höhere Motivation", "correct": true, "because": "Angenehmes Umfeld"}, {"text": "Weniger Krankheitstage", "correct": true, "because": "Ergonomie schützt"}, {"text": "Schnellere IT-Systeme", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Arbeitsraumgestaltung nur Ästhetik ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Funktionalität wichtig"}, {"text": "Ja", "correct": false, "because": "Mehr als Ästhetik"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Arbeitsraumgestaltung?', 3, '[{"text": "Ergonomie", "correct": true, "because": "Schützt Gesundheit"}, {"text": "Dekoration", "correct": false, "because": "Sekundär"}, {"text": "Kosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitsraumgestaltung fördert Zusammenarbeit. b) Sie ist gesetzlich vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gesetzlich nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine schlechte Arbeitsraumgestaltung?', 5, '[{"text": "Geringere Produktivität", "correct": true, "because": "Unbehagliches Umfeld"}, {"text": "Höhere Gesundheitsrisiken", "correct": true, "because": "Fehlende Ergonomie"}, {"text": "Schnellere Arbeit", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Arbeitsraumgestaltung unwichtig?', 3, '[{"text": "Beleuchtung", "correct": false, "because": "Beeinflusst Arbeitsklima"}, {"text": "Ergonomie", "correct": false, "because": "Schützt Gesundheit"}, {"text": "Mitarbeiternamen", "correct": true, "because": "Kein Gestaltungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Arbeitsraumgestaltung flexibel sein?', 3, '[{"text": "Ja", "correct": true, "because": "Anpassbar an Bedürfnisse"}, {"text": "Nein", "correct": false, "because": "Nicht statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Arbeitsraumgestaltung Lärmschutz umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Reduziert Ablenkung"}, {"text": "Nein", "correct": false, "because": "Teil der Gestaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für eine produktive Arbeitsraumgestaltung?', 4, '[{"text": "Offene Arbeitsbereiche", "correct": true, "because": "Fördert Kommunikation"}, {"text": "Einzelbüros", "correct": false, "because": "Weniger Zusammenarbeit"}, {"text": "Softwaretools", "correct": false, "because": "Kein Raumfaktor"}]');
